import React from 'react';
import { useParams } from 'react-router-dom';
import { moviesData } from '../data/moviesData';

function MovieDetail() {
  const { id } = useParams();
  const movie = moviesData[id] || Object.values(moviesData)[0];

  if (!movie) return <div className="text-white text-center py-20">영화를 찾을 수 없습니다.</div>;

  return (
    <div className="w-full min-h-screen bg-[#1c1c1e] text-white font-sans py-12 px-6">
      
      <div className="max-w-5xl mx-auto flex flex-col md:flex-row gap-10 items-start">
        
        {/* 좌측 포스터 이미지 */}
        <div className="w-full md:w-4/12 flex-shrink-0">
          <div className="w-full aspect-[3/4] rounded-2xl overflow-hidden shadow-2xl bg-zinc-800 border border-white/10">
            <img 
              src={process.env.PUBLIC_URL + movie.poster} 
              alt={movie.title} 
              className="w-full h-full object-cover" 
            />
          </div>
        </div>

        {/* 우측 상세 텍스트 영역 (가독성을 극대화한 폰트 크기와 줄 간격) */}
        <div className="w-full md:w-8/12 bg-[#252528] rounded-3xl p-8 border border-white/10 shadow-xl" style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '8px' }}>
              <span style={{ backgroundColor: '#503396', color: '#fff', fontSize: '12px', fontWeight: 'bold', padding: '4px 8px', borderRadius: '4px' }}>
                {movie.age}
              </span>
              <span style={{ color: '#a1a1aa', fontSize: '13px', fontWeight: 'bold' }}>
                {movie.year} · {movie.duration} · {movie.language}
              </span>
            </div>
            <h1 style={{ fontSize: '32px', fontWeight: '900', color: '#ffffff', letterSpacing: '-0.5px', margin: '0 0 10px 0' }}>
              {movie.title}
            </h1>
            <div style={{ width: '100%', height: '1px', backgroundColor: 'rgba(255,255,255,0.1)', margin: '15px 0' }}></div>
          </div>

          {/* 장르 및 평점 */}
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
            {movie.genres?.map((genre, idx) => (
              <span key={idx} style={{ backgroundColor: 'rgba(255,255,255,0.1)', color: '#d4d4d8', fontSize: '12px', padding: '4px 10px', borderRadius: '20px' }}>
                #{genre}
              </span>
            ))}
            <span style={{ backgroundColor: 'rgba(234, 179, 8, 0.2)', color: '#facc15', fontSize: '12px', fontWeight: 'bold', padding: '4px 10px', borderRadius: '20px' }}>
              ★ {movie.rating}
            </span>
          </div>

          {/* 출연진 */}
          {(movie.voiceCast || movie.casts) && (
            <div>
              <span style={{ fontSize: '11px', fontWeight: 'bold', textTransform: 'uppercase', color: '#c084fc', display: 'block', marginBottom: '4px', letterSpacing: '1px' }}>
                출연진
              </span>
              <p style={{ fontSize: '15px', fontWeight: '500', color: '#e4e4e7', margin: 0 }}>
                {movie.voiceCast || movie.casts}
              </p>
            </div>
          )}

          {/* 감독 */}
          <div>
            <span style={{ fontSize: '11px', fontWeight: 'bold', textTransform: 'uppercase', color: '#c084fc', display: 'block', marginBottom: '4px', letterSpacing: '1px' }}>
              감독
            </span>
            <p style={{ fontSize: '15px', fontWeight: '500', color: '#e4e4e7', margin: 0 }}>
              {movie.director}
            </p>
          </div>

          {/* 줄거리 */}
          <div>
            <span style={{ fontSize: '11px', fontWeight: 'bold', textTransform: 'uppercase', color: '#c084fc', display: 'block', marginBottom: '6px', letterSpacing: '1px' }}>
              줄거리
            </span>
            <p style={{ fontSize: '16px', lineHeight: '1.8', color: '#d4d4d8', margin: 0, textAlign: 'justify' }}>
              {movie.synopsis}
            </p>
          </div>

          {/* 예매하기 버튼 */}
          <div style={{ paddingTop: '10px' }}>
            <button style={{ width: '100%', padding: '16px', borderRadius: '12px', backgroundColor: '#503396', color: '#ffffff', fontWeight: '900', fontSize: '15px', border: '1px solid rgba(168, 85, 247, 0.3)', cursor: 'pointer' }}>
              예매하기
            </button>
          </div>

        </div>

      </div>

      {/* 갤러리 이미지 섹션 */}
      {movie.gallery && movie.gallery.length > 0 && (
        <div className="max-w-5xl mx-auto mt-16">
          <h3 style={{ fontSize: '12px', fontWeight: '900', letterSpacing: '2px', color: '#a1a1aa', textTransform: 'uppercase', marginBottom: '20px' }}>
            G A L L E R Y
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {movie.gallery.map((imgSrc, idx) => (
              <div key={idx} className="rounded-2xl overflow-hidden bg-zinc-800 aspect-video border border-white/10 shadow-lg">
                <img 
                  src={process.env.PUBLIC_URL + imgSrc} 
                  alt={`gallery-${idx}`} 
                  className="w-full h-full object-cover hover:scale-105 transition duration-500" 
                />
              </div>
            ))}
          </div>
        </div>
      )}

    </div>
  );
}

export default MovieDetail;
